mapper.select:
SELECT 

WHERE e.deleted = 0 AND e.employee_code = #{employeeCode}
LIMIT 1

SELECT FROM hr_department d LEFT JOIN hr_department pd ON d.parent_dept_id = pd.id WHERE d.deleted = 0
AND d.dept_code IN #{code}
ORDER BY d.sort_order, d.id

SELECT FROM hr_department d JOIN hr_department pd ON d.parent_dept_id = pd.id WHERE d.deleted = 0 AND pd.dept_code = #{parentDeptCode}
AND d.dept_code IN #{code}
ORDER BY d.sort_order, d.id

SELECT FROM hr_evaluation_result r JOIN hr_evaluation_task t ON r.task_id = t.id JOIN hr_evaluation_cycle c ON t.cycle_id = c.id JOIN hr_employee e ON r.employee_id = e.id LEFT JOIN hr_department ed ON e.dept_id = ed.id WHERE r.deleted = 0 AND e.employee_code = #{employeeCode}
AND ed.dept_code IN #{code}
ORDER BY c.end_date DESC, r.id DESC
